import socket
import sys
import os
import time
import subprocess
"""
HexByteConversion

Convert a byte string to it's hex representation for output or visa versa.

ByteToHex converts byte string "\xFF\xFE\x00\x01" to the string "FF FE 00 01"
HexToByte converts string "FF FE 00 01" to the byte string "\xFF\xFE\x00\x01"
"""

# -------------------------------------------------------------------------------


def ByteToHex(byteStr):
    """
    Convert a byte string to it's hex string representation e.g. for output.
    """

    # Uses list comprehension which is a fractionally faster implementation than
    # the alternative, more readable, implementation below
    #    hex = []
    #    for aChar in byteStr:
    #        hex.append( "%02X " % ord( aChar ) )
    #    return ''.join( hex ).strip()

    return ''.join(["%02X" % ord(x) for x in byteStr]).strip()

# -------------------------------------------------------------------------------


def HexToByte(hexStr):
    """
    Convert a string hex byte values into a byte string. The Hex Byte values may
    or may not be space separated.
    """
    # The list comprehension implementation is fractionally slower in this case
    #    hexStr = ''.join( hexStr.split(" ") )
    #    return ''.join( ["%c" % chr( int ( hexStr[i:i+2],16 ) ) \
    #                                   for i in range(0, len( hexStr ), 2) ] )

    bytes = []

    hexStr = ''.join(hexStr.split(" "))

    for i in range(0, len(hexStr), 2):
        bytes.append(chr(int(hexStr[i:i + 2], 16)))

    return ''.join(bytes)

# -------------------------------------------------------------------------------


logfile = "log.txt"
if len(sys.argv) > 1:
    logfile = sys.argv[1]

sys.stdout = os.fdopen(sys.stdout.fileno(), 'w', 0)
tee = subprocess.Popen(["tee", logfile], stdin=subprocess.PIPE)
if tee.stdin is None:
    print("Error opening log file")  # noqa: T201
    sys.exit()
else:
    os.dup2(tee.stdin.fileno(), sys.stdout.fileno())
    os.dup2(tee.stdin.fileno(), sys.stderr.fileno())


def startMeas(s):
    for fsp in range(1, 2):
        for dsp in range(6):
            print("")  # noqa: T201
            for core in range(4):
                # print "%d %d %d:" % (fsp, dsp+1, core+1),
                BrowserStartIdleMeasurementReq = "00 00 1B E4 %00d %00d 12 00 00 00 00 00 00 14 00 00 00 00 00 64" % \
                                                 (12, 30 + 10 * dsp + core + 1)

                data1 = HexToByte(BrowserStartIdleMeasurementReq)

                if core == 3 and (dsp == 1 or dsp == 3 or dsp == 5):
                    try:
                        s.send(data1)
                        s.settimeout(1)
                        print("Sending start to %d %d %d:" % (fsp, dsp + 1, core + 1))  # noqa: T201

                    except Exception:
                        print("send failed: maybe connection is currently used by LTEBrowser")  # noqa: T201
                        # raw_input("\r\npress <return> to exit\r\n")
                        # s.close()
                        return

# function for getting current time


def stopMeas():
    for fsp in range(1, 2):
        for dsp in range(6):
            print("")  # noqa: T201
            for core in range(4):
                print("%d %d %d:" % (fsp, dsp + 1, core + 1))  # noqa: T201

                BrowserStopIdleMeasurementReq = "00 00 1B E5 %00d %00d 12 00 00 00 00 00 00 14 00 00 00 00 00 00" % \
                                                (12, 30 + 10 * dsp + core + 1)

                data3 = HexToByte(BrowserStopIdleMeasurementReq)

                if core == 3 and (dsp == 1 or dsp == 3 or dsp == 5):
                    try:
                        s.send(data3)

                    except Exception:
                        print("send failed: maybe connection is currently used by LTEBrowser")  # noqa: T201
                        # raw_input("\r\npress <return> to exit\r\n")
                        # s.close()
                        return


def openSocket():
    # create an INET, STREAMing socket
    s = socket.socket(
        socket.AF_INET, socket.SOCK_STREAM)
    try:
        s.connect(("192.168.255.1", 15005))

    except Exception:
        print("connect failed: maybe connection is currently used by LTEBrowser")  # noqa: T201
        # raw_input("\r\npress <return> to exit\r\n")
        return False

    return s


