sleeptime = 10  # default refresh time in seconds


if len(sys.argv) > 2:
    sleeptime = int(sys.argv[2])

s = openSocket()

startMeas(s)

while 1:
    os.system('CLS')
    try:

        getCpuLoads(s)
        t = time.localtime()
        print("\r\n%02i.%02i.%02i %02i:%02i:%02i " % (t[0:6]))  # noqa: T201
        print("update every %i s. Press ^C to exit" % (sleeptime))  # noqa: T201
        time.sleep(sleeptime)
    except Exception:
        print("Aborted")  # noqa: T201
        stopMeas()
        s.close()
        sys.exit()


